 * @hidden N
 */
scwin.ipt_chgTpCd0_onclick = function(e){
    try {
        scwin.chgTpCd('All')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil20500.ipt_chgTpCd0_onclick' }); }
