/**
 * @method
 * @name krxpage_pagenavigator_96_onclick
 * @description krxpage_pagenavigator_96 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_96_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_SearchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_96.page' }); } await scwin.tx_fn_Search(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/company/companyChange.do",
        ref: "dma_SearchReq",
        target: "dlt_companyChangeList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_96").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    let isChecked = false;
    for (let i = 0; i < 8; i++) {
        if ($("#chgTpCd" + i).is(":checked")) {
            isChecked = true;
        }
    }
    if (!isChecked) {
        await $c.win.alert("검색 조건을 1개이상 선택하세요.");
        return;
    }
    const frm = (document.changeInfoForm || { elements: [] });
    $c.util.getComponent('dma_SearchReq').set('method', 'searchCompanyChange');
    frm.action = 'companyChange.do';
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name chgTpCd
 * @description chg Tp Cd 처리
 * @param {String} _flag _flag
 * @returns {void}
 * @hidden N
 */
scwin.chgTpCd = function (_flag) {
    if (_flag === 'All') {
        if ($("#ipt_chgTpCd0").is(":checked")) {
            for (let i = 0; i < 8; i++) {
                $("#chgTpCd" + i).attr({ "checked": "checked" });
            }
        } else {
            for (let i = 0; i < 8; i++) {
                $("#chgTpCd" + i).removeAttr("checked");
            }
        }
    }
};
